#include <stdio.h>

int main(void) {
    double a = 0.1, b = 0.2, c = 0.3;

    printf("=== why 0.1 + 0.2 != 0.3 ===\n");
    printf("  0.1          = %.20f\n", a);
    printf("  0.2          = %.20f\n", b);
    printf("  0.1 + 0.2    = %.20f\n", a + b);
    printf("  0.3          = %.20f\n", c);
    printf("  (0.1+0.2)==0.3           -> %s\n", ((a + b) == c) ? "true" : "false");
    printf("  exact difference         = %.20e\n", (a + b) - c);

    printf("\n=== catastrophic absorption (big eats small) ===\n");
    double big = 1e16;
    printf("  (1e16 + 1.0) - 1e16      = %.1f   (the 1.0 is completely lost)\n", (big + 1.0) - big);
    printf("  1e16 + 1.0 == 1e16       -> %s\n", ((big + 1.0) == big) ? "true" : "false");

    printf("\n=== naive vs Kahan compensated summation ===\n");
    double naive = 0.0, kahan = 0.0, comp = 0.0;
    int i;
    for (i = 0; i < 1000000; i++) {
        double y;
        naive += 0.1;

        y = 0.1 - comp;
        {
            double t = kahan + y;
            comp = (t - kahan) - y;
            kahan = t;
        }
    }
    printf("  sum of 0.1 one million times, naive = %.10f\n", naive);
    printf("  sum of 0.1 one million times, Kahan = %.10f\n", kahan);
    printf("  error of naive                     = %.6e\n", naive - 100000.0);
    printf("  error of Kahan                     = %.6e\n", kahan - 100000.0);

    printf("\n=== tolerance comparison ===\n");
    double diff = (a + b) - c;
    double eps = 1e-9;
    printf("  fabs(diff) < eps with eps=1e-9   -> %s\n",
           ((diff < eps) && (-diff < eps)) ? "true" : "false");
    printf("\nrule: never compare floats with ==; use an absolute or relative tolerance\n");
    printf("for money use integer minor units (cents) or a decimal type\n");
    return 0;
}
